def equal(a,b):
 if type(a) in (int,float) and type(b) in (int,float):return a==b
 if type(a) is not type(b): return False
 if isinstance(a,dict): return a.keys()==b.keys() and all(equal(a[k],b[k]) for k in a)
 if isinstance(a,list): return len(a)==len(b) and all(equal(x,y) for x,y in zip(a,b))
 return a==b

def get(root,path):
 v=root
 for k in path.split('.') if path else []:
  if not isinstance(v,dict) or k not in v:return MISSING
  v=v[k]
 return v

def nonvalue(v):
 if v is MISSING or v is None:return True
 if isinstance(v,str):return v.strip().lower() in UNRESOLVED
 if isinstance(v,list):return any(nonvalue(x) for x in v)
 return False

def nonvalue_field(v,field,check):return nonvalue(v) or (field in check.get('nonempty_fields',[]) and isinstance(v,list) and len(v)==0)

def failure(field,result,owner):return {'field':field,'result':result,'return_owner':owner}

def run_check(raw,check):
 op=check['op'];out=[]
 if 'requires_parent' in check and nonvalue(get(raw,check['requires_parent'])):return out
 if op=='compare_member_pairs':
  for p in check['pairs']:
   a,b=get(raw,p['left']),get(raw,p['right'])
   if nonvalue(a) or nonvalue(b):
    ov=p.get('claim_override');claims=get(raw,'claims')
    if ov and ov['claim'] in claims and not nonvalue(a):out.append(failure(ov['field'],ov['result'],p['owner']))
    else:
     if p.get('attribute_original_missing') and nonvalue(a):out.append(failure('work.'+p['left'].split('.')[-1] if nonvalue(b) else p['left'],'unobserved_work_reference' if nonvalue(b) else 'unobserved_original_work',p['owner']))
     else:out.append(failure(p.get('missing_field',p['field']),p['missing'],p['owner']))
   elif not equal(a,b):out.append(failure(p['field'],p['different'],p['owner']))
 elif op=='compare_if_both':
  for p in check['pairs']:
   a,b=get(raw,p['left']),get(raw,p['right'])
   if not nonvalue(a) and not nonvalue(b) and not equal(a,b):out.append(failure(p['field'],p['different'],p['owner']))
 elif op=='compare_literal_members':
  for p in check['members']:
   a=get(raw,p['path'])
   if nonvalue(a):out.append(failure(p['field'],p['missing'],p['owner']))
   elif not equal(a,p['literal']):out.append(failure(p['field'],p['different'],p['owner']))
 elif op=='require_both_members':
  for p in check['pairs']:
   if nonvalue(get(raw,p['left'])) or nonvalue(get(raw,p['right'])):out.append(failure(p['field'],p['missing'],p['owner']))
 elif op=='literal_group':
  for m in check['members']:
   v=get(raw,m['path'])
   if nonvalue(v):
    if check.get('skip_missing_members'):continue
    out.append(failure(check['field'],check['missing'],check['owner']));break
   if not equal(v,m['literal']):out.append(failure(check['field'],check['different'],check['owner']));break
 elif op=='identity_separation':
  worker=get(raw,check['worker_path'])
  if nonvalue(worker):return out
  for m in check['resources']:
   v=get(raw,m['path'])
   if nonvalue(v):out.append(failure(m['field'],check['missing'],check['owner']));break
   if equal(worker,v):out.append(failure(m['field'],check['result'],check['owner']));break
 elif op=='enum_member':
  v=get(raw,check['path'])
  if nonvalue(v):out.append(failure(check['field'],check['missing'],check['owner']))
  elif v in check['known_values']:
   result=check['known_values'][v]
   if result is not None:out.append(failure(check['field'],result,check['owner']))
  else:out.append(failure(check['field'],check['unknown'],check['owner']))
 elif op=='equal_path_finding':
  a,b=get(raw,check['left']),get(raw,check['right'])
  if not nonvalue(a) and not nonvalue(b) and equal(a,b):out.append(failure(check['field'],check['result'],check['owner']))
 elif op=='isolation_state':
  method=get(raw,check['method_path']);state=get(raw,check['path'])
  if not nonvalue(method) and isinstance(method,str) and check['unavailable_marker'].upper() in method.upper():out.append(failure(check['method_field'],check['unavailable'],check['owner']))
  elif not nonvalue(method) and nonvalue(state):out.append(failure(check['field'],check['missing'],check['owner']))
  elif not nonvalue(method) and not equal(state,check['enforced']):out.append(failure(check['field'],check['not_enforced'] if equal(state,check['not_enforced_input']) else check['unknown'],check['owner']))
 elif op=='require_members':
  for m in check['members']:
   if nonvalue(get(raw,m['path'])):out.append(failure(m['field'],m['missing'],m['owner']))
 elif op=='literal_member':
  a=get(raw,check['path'])
  if nonvalue(a):out.append(failure(check['field'],check['missing'],check['owner']))
  elif not equal(a,check['literal']):out.append(failure(check['field'],check['different'],check['owner']))
 elif op=='compare_scope':
  ev=get(raw,check['evidence_path'])
  if nonvalue(ev):out.append(failure(check['empty_parent_field'] if nonvalue(get(raw,check['evidence_path'].split('.')[0])) else check['prefix'][:-1],check['missing'],check['owner']))
  else:
   ref=get(raw,check['reference_path'])
   for f in check['fields']:
    a=get(ev,f);b=get(ref,f)
    if nonvalue_field(b,f,check):out.append(failure('scope.'+f,check['missing'],check['reference_owners'][f]))
    elif nonvalue_field(a,f,check):out.append(failure(check['prefix']+f,check['missing'],check['owner']))
    elif not (set(a)==set(b) if f in check.get('set_fields',[]) else equal(a,b)):
     result=check['different']
     for override in check.get('conditional_result',[]):
      if override['field']==f and override['claim'] in get(raw,override['claims_path']):result=override['result']
     out.append(failure(check['prefix']+f,result,check['owner']))
 elif op in ('claim_literal_finding','claim_or_member_finding'):
  claims=get(raw,check['claims_path']); basis=get(raw,check['condition_path'])
  if not nonvalue(basis) and (check['claim'] in claims or (op=='claim_or_member_finding' and isinstance(basis,dict) and check['independent_member'] in basis)):out.append(failure(check['field'],check['result'],check['owner']))
 elif op=='claim_scope_override':
  claims=get(raw,check['claims_path']);a=get(raw,check['scope_path']);b=get(raw,check['reference_path'])
  if check['claim'] in claims and not nonvalue(a) and not nonvalue(b) and not equal(a,b):out.append(failure(check['finding_field'],check['result'],check['owner']))
 else:raise AssertionError('未定義の論理演算子 '+str(op))
 return out

def unique_findings(rows):
 out=[]
 for row in rows:
  if not any(equal(row,old) for old in out):out.append(row)
 return out

def bind_supplied_context(program,raw):
 out=[]
 scope=get(raw,'original_scope')
 for field in program['scope_required_fields']:
  value=get(scope,field)
  if nonvalue(value) or (field=='resources' and value==[]):
   if field=='worker' and program['work_relation'] and nonvalue(get(raw,'original_work_before.worker')):continue
   out.append(failure('scope.'+field,'unobserved',REFERENCE_OWNERS[field]))
 worker=get(raw,'original_scope.worker');before=get(raw,'original_work_before.worker')
 if not nonvalue(worker) and not nonvalue(before) and not equal(worker,before):out.append(failure('work.worker','wrong_identity_or_owner','OS-work-owner'))
 if not program['work_relation'] and nonvalue(before):out.append(failure('work.worker','missing','OS-work-owner'))
 selected_worker=before if nonvalue(worker) else worker
 identities=[];valid_identities=True;conflated=False
 for side in ['source','destination']:
  root='original_'+side+'_resource';record=get(raw,root)
  for field in ['identity','revision','environment','source_ref','capacity_state']:
   value=get(record,field)
   if nonvalue(value):out.append(failure(side+'.'+field,'unobserved','INFRA-resource-source'))
  owner=get(record,'owner')
  if nonvalue(owner):out.append(failure(side+'.owner','unobserved','INFRA-resource-source'))
  elif not equal(owner,'INFRA'):out.append(failure(side+'.owner','wrong_identity_or_owner','INFRA-resource-source'))
  identity=get(record,'identity')
  if nonvalue(identity):valid_identities=False
  else:identities.append(identity)
  if not nonvalue(selected_worker) and not nonvalue(identity) and equal(selected_worker,identity):
   conflated=True;out.append(failure(side+'.identity','worker_resource_conflated','INFRA-resource-source'))
  env=get(record,'environment');reference_env=get(scope,'environment')
  if not nonvalue(env) and not nonvalue(reference_env) and not equal(env,reference_env):out.append(failure(side+'.environment','foreign_or_unseen','INFRA-resource-source'))
 resources=get(scope,'resources')
 if valid_identities and not conflated and not nonvalue(resources) and resources!=[] and set(resources)!=set(identities):out.append(failure('scope.resources','foreign_or_unseen','INFRA-resource-source'))
 if program['assess_isolation']:
  isolation=get(raw,'original_isolation')
  if nonvalue(isolation):out.append(failure('original_isolation','unobserved','HELIX-SECURITY'))
  else:
   owner=get(isolation,'owner')
   if nonvalue(owner):out.append(failure('isolation.owner','unobserved','HELIX-SECURITY'))
   elif not equal(owner,'HELIX-SECURITY'):out.append(failure('isolation.owner','wrong_identity_or_owner','HELIX-SECURITY'))
   value=get(isolation,'constraint_ref');reference=get(scope,'constraint_ref')
   if nonvalue(value):out.append(failure('isolation.constraint_ref','unobserved','HELIX-SECURITY'))
   elif not nonvalue(reference) and not equal(value,reference):out.append(failure('isolation.constraint_ref','foreign_or_unseen','HELIX-SECURITY'))
   if program['assess_isolation_status']:
    for check in program['isolation_status_checks']:out.extend(run_check(raw,check))
 if program['assess_observation']:
  evidence=get(raw,'original_state_evidence')
  if nonvalue(evidence):out.append(failure('original_state_evidence','unobserved','INFRA-resource-source'))
  else:
   for field in ['ref','state','source_ref']:
    value=get(evidence,field)
    if nonvalue(value):out.append(failure('state_evidence.'+field,'unobserved','INFRA-resource-source'))
    elif field=='state' and not equal(value,'observed_in_fixture_only'):out.append(failure('state_evidence.state','unobserved','INFRA-resource-source'))
   value=get(evidence,'source_ref');reference=get(raw,'original_destination_resource.source_ref')
   if not nonvalue(value) and not nonvalue(reference) and not equal(value,reference):out.append(failure('state_evidence.source_ref','foreign_or_unseen','INFRA-resource-source'))
  if program['assess_observation_scope']:out.extend(run_check(raw,program['observation_scope_check']))
 return out

def work_presence(program,raw):
 if not program['work_relation']:return {'mode':'not_assessed','field_results':{},'information_state':'not_assessed'}
 results={}
 for field in WORK_FIELDS:
  a=get(raw,'original_work_before.'+field);b=get(raw,'submitted_work_after.'+field)
  results[field]='unknown' if nonvalue(a) or nonvalue(b) else 'content_corresponding_in_fixture_only' if equal(a,b) else 'content_conflict'
 state='unknown' if 'unknown' in results.values() else 'content_conflict' if 'content_conflict' in results.values() else 'content_corresponding_in_fixture_only'
 return {'mode':'presence_and_content','field_results':results,'information_state':state}

def revision_bindings(raw):
 out={}
 for side in ['source','destination']:
  record=get(raw,'original_'+side+'_resource');row={}
  for field in ['identity','revision']:
   value=get(record,field)
   if value is not MISSING:row[field]=value
  row['comparison']='unobserved' if nonvalue(get(record,'identity')) or nonvalue(get(record,'revision')) else 'independent_target_unprovided'
  out[side]=row
 return out

def interpret(program,raw):
 out={}
 for key,path in program['projection'].items():
  v=get(raw,path)
  if v is not MISSING:out[key]=v
 failures=[]
 for c in program['checks']:failures.extend(run_check(raw,c))
 failures.extend(bind_supplied_context(program,raw))
 # rejected claim order follows raw claim list; domain comes from the formal program
 claims=get(raw,'claims');rejected=[x for x in claims if x in program['claim_domain']];unrecognized=[x for x in claims if x not in program['claim_domain']]
 if unrecognized:failures.append(failure('claims','unrecognized_claim',None))
 failures=unique_findings(failures)
 owners=[]
 for f in failures:
  if f['return_owner'] not in owners:owners.append(f['return_owner'])
 out['information_state']=program['state_rule']['when_failures'] if failures else program['state_rule']['otherwise']
 out['work_reference_preservation']='corresponding_in_fixture_only'
 if program['work_relation']:
  before=get(raw,'original_work_before');after=get(raw,'submitted_work_after')
  out['work_reference_preservation']='corresponding_in_fixture_only' if equal(before,after) else 'submitted_content_conflict'
 out['failure_reasons']=failures;out['return_owners']=owners;out['rejected_claims']=rejected;out['actual_effects']=program['effects']
 out['work_reference_assessment']=work_presence(program,raw);out['resource_revision_bindings']=revision_bindings(raw);out['unrecognized_claims']=unrecognized
 return out

def run_program(function_ref,raw):
 return interpret(PROGRAMS[function_ref],raw)


def pointer_member(path,key):
 return path+'/'+str(key).replace('~','~0').replace('/','~1')

def input_issue(value,spec,path):
 if 'same_as' in spec:return input_issue(value,SCHEMAS[spec['same_as']],path)
 expected=spec['type']
 if value is MISSING:return {'path':path,'expected_type':expected,'kind':'missing_member'}
 if value is None and (spec.get('nullable',False) or expected=='nullable-record'):return None
 if expected in ['record','nullable-record']:
  if not isinstance(value,dict):return {'path':path,'expected_type':expected,'kind':'wrong_json_kind'}
  for field,child in spec['fields'].items():
   if field not in value and child.get('optional',False):continue
   result=input_issue(value.get(field,MISSING),child,pointer_member(path,field))
   if result is not None:return result
  for field in sorted(value):
   if field not in spec['fields']:return {'path':pointer_member(path,field),'expected_type':'no_additional_member','kind':'undeclared_member'}
  return None
 if expected=='array':
  if not isinstance(value,list):return {'path':path,'expected_type':expected,'kind':'wrong_json_kind'}
  for index,item in enumerate(value):
   result=input_issue(item,spec['items'],pointer_member(path,index))
   if result is not None:return result
  return None
 valid=(expected=='string' and isinstance(value,str)) or (expected=='integer' and type(value)is int) or (expected=='boolean' and type(value)is bool) or (expected=='enum' and isinstance(value,str) and value in spec['values'])
 if not valid:return {'path':path,'expected_type':expected,'kind':'wrong_json_kind'}
 return None

def invoke_logical(function_ref,raw):
 program=PROGRAMS[function_ref]
 issue=input_issue(raw,SCHEMAS[program['input_type']],'')
 if issue is not None:return {'tag':'not_invoked_outside_declared_domain','issue':issue}
 return {'tag':'assessed_in_declared_domain','assessment':run_program(function_ref,raw)}
